-- 0026 — Recettes étoffées : introduction plus riche (description) et conseils de
-- conservation (nouvelle colonne storage_note) : durée au réfrigérateur, congélation,
-- réchauffage. Durées volontairement prudentes (1 jour pour le riz cuit, les fruits de mer,
-- la mayonnaise et les œufs crus). Aucune modification d'ingrédient ni de quantité.

alter table public.recipes
  add column storage_note text
  check (storage_note is null or char_length(btrim(storage_note)) between 3 and 500);

comment on column public.recipes.storage_note is
  'Conseils de conservation affichés sur la fiche recette (réfrigérateur, congélation, réchauffage).';

update public.recipes r
set description = v.description, storage_note = v.storage_note
from (values
  ('agneau-raisins-semoule', 'Un mijoté inspiré des tajines, où l''agneau fond doucement avec les carottes, la cannelle et le cumin. Les raisins secs et le miel apportent une touche sucrée qui équilibre les épices, et les amandes grillées un peu de croquant. Un plat généreux pour un repas du week-end, qui se prépare tranquillement pendant qu''il mijote.', 'Se garde 3 jours au réfrigérateur dans une boîte hermétique, et c''est encore meilleur le lendemain. La viande et sa sauce se congèlent 3 mois. Réchauffer à feu doux à couvert, avec un peu d''eau ; préparer la semoule au dernier moment.'),
  ('aubergines-parmesane', 'La « parmigiana » italienne : des tranches d''aubergines rôties, une sauce tomate à l''ail, de la mozzarella et du basilic, montées en couches et gratinées au parmesan. Fondant, généreux et entièrement végétarien. Elle se prépare à l''avance et se réchauffe très bien.', 'Se garde 3 jours au réfrigérateur, couvert. Se congèle 2 mois, en parts. Réchauffer 15 à 20 minutes au four à 180 °C, couvert d''une feuille d''aluminium pour que le dessus ne brûle pas.'),
  ('blanquette-veau', 'Le grand classique de la cuisine familiale française : un veau cuit doucement dans un bouillon parfumé, puis nappé d''une sauce blanche onctueuse relevée au citron. Les champignons et les carottes complètent ce plat réconfortant, idéal pour un déjeuner du dimanche.', 'Se garde 3 jours au réfrigérateur dans une boîte hermétique. La viande et sa sauce se congèlent 3 mois. Réchauffer à feu très doux sans faire bouillir, pour que la sauce ne tourne pas ; le riz se garde 1 jour seulement.'),
  ('boeuf-bourguignon', 'Le mijoté emblématique de Bourgogne : des morceaux de bœuf longuement cuits dans le vin rouge avec lardons, carottes et champignons. La sauce devient sombre, brillante et pleine de goût. À préparer la veille si possible : il est encore meilleur réchauffé.', 'Se garde 3 jours au réfrigérateur dans une boîte hermétique. Se congèle très bien, 3 mois. Réchauffer à feu doux à couvert, en remuant de temps en temps, jusqu''à ce que la sauce frémisse.'),
  ('boeuf-brocoli-saute', 'Un sauté express à l''asiatique : des lanières de bœuf saisies à feu très vif, un brocoli qui reste croquant et une sauce soja relevée au gingembre et à l''ail. La fécule enrobe la viande pour la garder tendre et lier la sauce. Prêt en une vingtaine de minutes.', 'À déguster de préférence tout de suite, le brocoli ramollit en attendant. Se garde 1 jour au réfrigérateur à cause du riz, refroidi rapidement. Réchauffer 2 minutes à la poêle à feu vif. Ne se congèle pas bien.'),
  ('bolognaise', 'La sauce tomate à la viande que tout le monde aime, mijotée doucement avec l''oignon, la carotte et les herbes jusqu''à devenir épaisse et parfumée. Elle se double facilement : la sauce se garde et se congèle, pratique pour les soirs pressés.', 'La sauce se garde 3 jours au réfrigérateur et se congèle 3 mois, en portions. Les pâtes cuites se gardent 2 jours, à part. Réchauffer la sauce à feu doux et cuire les pâtes au dernier moment si possible.'),
  ('boulettes-boeuf-sauce-tomate', 'Des boulettes moelleuses au persil, dorées puis mijotées dans une sauce tomate, servies sur des spaghetti. Un plat convivial qui plaît aux petits comme aux grands. Les boulettes peuvent être façonnées à l''avance et gardées au frais.', 'Les boulettes et leur sauce se gardent 3 jours au réfrigérateur et se congèlent 3 mois. Les spaghetti cuits se gardent 2 jours, à part. Réchauffer à feu doux à couvert.'),
  ('bowl-saumon-fume-avocat', 'Un bol frais et coloré, sans cuisson à part celle du riz : saumon fumé, avocat crémeux, concombre et mangue, le tout relevé d''une sauce soja au citron vert. Parfait pour un déjeuner rapide ou un soir d''été.', 'À assembler et déguster tout de suite : l''avocat noircit et le poisson ne doit pas attendre. Le riz cuit se garde 1 jour au réfrigérateur, refroidi rapidement. Ne se congèle pas.'),
  ('buddha-bowl-quinoa', 'Un bol complet et végétarien : quinoa, patate douce et pois chiches rôtis au paprika, épinards frais et avocat. Les textures se répondent, fondant, croquant et crémeux. Les éléments rôtis se préparent à l''avance pour les repas de la semaine.', 'Le quinoa et les légumes rôtis se gardent 3 jours au réfrigérateur, dans des boîtes séparées. Ajouter l''avocat et le citron au moment de servir. Se déguste froid ou réchauffé ; ne se congèle pas bien.'),
  ('cabillaud-pane-haricots-verts', 'Un poisson blanc enrobé d''une chapelure dorée et croustillante, accompagné de haricots verts juste cuits. Une façon simple de faire aimer le poisson, avec un filet de citron pour la fraîcheur.', 'Meilleur tout juste cuit, la panure ramollit ensuite. Se garde 1 jour au réfrigérateur. Réchauffer 8 à 10 minutes au four à 180 °C pour retrouver un peu de croustillant. Ne se congèle pas une fois cuit.'),
  ('cabillaud-poireaux', 'Un plat doux et délicat : des dos de cabillaud cuits à l''étouffée sur une fondue de poireaux à la crème. Le poisson reste nacré et moelleux, la fondue fait office de sauce. Un repas léger et réconfortant.', 'Se garde 1 jour au réfrigérateur dans une boîte hermétique. Réchauffer à feu très doux à couvert, juste le temps que le poisson soit chaud, pour qu''il ne se dessèche pas. Ne se congèle pas bien.'),
  ('cake-banane', 'Le meilleur moyen d''utiliser des bananes bien mûres : un cake moelleux, parfumé et peu sucré, avec le croquant des noix. Parfait au petit-déjeuner ou au goûter, il se prépare en quelques minutes.', 'Se garde 3 à 4 jours à température ambiante, bien emballé. Se congèle 2 mois, en tranches : on les sort au fur et à mesure. Une tranche passée quelques secondes au grille-pain retrouve tout son moelleux.'),
  ('chili-con-carne', 'Le plat mijoté tex-mex par excellence : viande hachée, haricots rouges et tomates relevés au cumin, au paprika et au piment. Copieux et chaleureux, il se dose selon votre goût pour le piquant et se prépare volontiers en grande quantité.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois, en portions : il est même meilleur réchauffé. Réchauffer à feu doux en ajoutant un peu d''eau s''il a épaissi. Le riz cuit se garde 1 jour seulement.'),
  ('chili-sin-carne', 'La version végétarienne du chili : haricots rouges, maïs, poivron et tomates mijotés avec cumin et paprika. Aussi généreux que l''original, économique, et encore meilleur le lendemain.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux avec un peu d''eau. Le riz cuit se garde 1 jour, à part.'),
  ('chou-fleur-roti-curry', 'Rôti au four avec du curry, le chou-fleur devient doré, presque caramélisé, et prend un goût insoupçonné. Les pois chiches croustillants et la sauce au yaourt citronnée complètent ce plat végétarien simple et parfumé.', 'Les légumes rôtis se gardent 3 jours au réfrigérateur ; la sauce au yaourt 2 jours, à part. Réchauffer 10 minutes au four à 200 °C pour garder du croustillant. Le riz cuit se garde 1 jour. Ne se congèle pas bien.'),
  ('coquillettes-jambon-emmental', 'Le plat réconfort par excellence, prêt en un quart d''heure : des coquillettes fondantes, du jambon et de l''emmental qui file. Simple, économique, et toujours apprécié des enfants.', 'Se garde 2 jours au réfrigérateur dans une boîte hermétique. Réchauffer à la poêle à feu doux avec une noisette de beurre ou un filet d''eau, en remuant. Ne se congèle pas bien.'),
  ('cotes-porc-pommes', 'Un accord sucré-salé de la cuisine normande : des côtes de porc dorées, des pommes caramélisées au beurre et une sauce à la moutarde et à la crème. Un plat de saison, simple et très parfumé.', 'Se garde 2 jours au réfrigérateur dans une boîte hermétique. Réchauffer à feu doux à couvert, dans la sauce, pour que la viande ne se dessèche pas. Ne se congèle pas bien.'),
  ('courgettes-farcies-boulgour', 'Des courgettes garnies d''une farce de boulgour, tomate, feta et menthe, puis rôties au four. Un plat végétarien d''inspiration méditerranéenne, frais et parfumé, qui se prépare à l''avance.', 'Se garde 3 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C, ou déguster tiède. Ne se congèle pas bien, la courgette rend de l''eau.'),
  ('couscous-legumes', 'Un couscous végétarien généreux : carottes, navet, courgettes et pois chiches cuits dans un bouillon parfumé au cumin, servis avec une semoule légère. La harissa à part permet à chacun de doser le piquant.', 'Les légumes et leur bouillon se gardent 3 jours au réfrigérateur et se congèlent 3 mois. La semoule se garde 2 jours, à part. Réchauffer le bouillon à feu doux et la semoule avec un peu d''eau.'),
  ('crepes-jambon-fromage', 'Des crêpes maison garnies de jambon et d''emmental fondu, pliées en quatre et servies bien chaudes. Un repas simple et convivial, qui se prépare avec les placards du quotidien.', 'Les crêpes nature se gardent 2 jours au réfrigérateur, bien filmées, et se congèlent 2 mois, séparées par du papier. Garnies, les réchauffer 1 à 2 minutes par face à la poêle.'),
  ('crevettes-curry-coco', 'Des crevettes tendres dans une sauce au curry et au lait de coco, avec le poivron et une touche de citron vert. Un plat exotique prêt en moins de 30 minutes, doux et parfumé.', 'Se garde 1 jour au réfrigérateur, refroidi rapidement, comme le riz. Réchauffer à feu doux, juste le temps que ce soit chaud : les crevettes durcissent si elles recuisent. Ne se congèle pas.'),
  ('croque-monsieur', 'Le classique des cafés français : pain de mie, jambon et emmental, dorés au four jusqu''à ce que le fromage soit fondant et croustillant. Un repas rapide, prêt en 20 minutes.', 'Meilleur tout juste sorti du four. Se garde 1 jour au réfrigérateur ; le réchauffer 5 minutes au four à 200 °C. On peut aussi les assembler à l''avance et les garder crus au frais jusqu''au soir.'),
  ('crumble-pommes', 'Un dessert d''automne réconfortant : des pommes fondantes parfumées à la cannelle sous une pâte sablée dorée et croustillante. Facile à réussir, il se prépare sans rouleau ni moule à tarte.', 'Se garde 3 jours au réfrigérateur, couvert. Réchauffer 10 minutes au four à 160 °C pour retrouver le croustillant. La pâte crue, émiettée, se congèle 2 mois et s''utilise sans décongeler.'),
  ('curry-pois-chiches-epinards', 'Un curry végétarien express : pois chiches, tomates et lait de coco relevés au gingembre et au curry, avec des épinards ajoutés à la fin. Doux, parfumé et rassasiant, il se prépare avec des ingrédients de placard.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux avec un peu d''eau. Le riz cuit se garde 1 jour, à part.'),
  ('dinde-creme-champignons', 'Des escalopes dorées nappées d''une sauce crémeuse aux champignons et aux échalotes. Un plat de semaine simple et doux, prêt en une demi-heure.', 'Se garde 2 jours au réfrigérateur dans une boîte hermétique. Réchauffer à feu doux à couvert, dans la sauce. Le riz cuit se garde 1 jour. Ne se congèle pas bien, la sauce à la crème tranche.'),
  ('endives-jambon', 'Le gratin du Nord par excellence : des endives fondantes roulées dans du jambon, nappées de béchamel et gratinées à l''emmental. Un plat d''hiver économique et réconfortant.', 'Se garde 3 jours au réfrigérateur. Se congèle 2 mois. Réchauffer 20 minutes au four à 180 °C, couvert d''une feuille d''aluminium.'),
  ('fajitas-poulet', 'Des tortillas garnies de poulet mariné aux épices et au citron vert, de poivrons et d''oignon sautés, avec crème, cheddar et salade. Un repas à composer soi-même, parfait pour les soirées entre amis.', 'Le poulet et les légumes se gardent 2 jours au réfrigérateur. Réchauffer 2 à 3 minutes à la poêle à feu vif et garnir les tortillas au dernier moment. Ne se congèle pas bien.'),
  ('falafels-four', 'Des boulettes de pois chiches aux herbes et au cumin, cuites au four plutôt que frites, croustillantes dehors et moelleuses dedans. Servies avec une sauce au yaourt citronnée, elles font un repas végétarien complet.', 'Se gardent 3 jours au réfrigérateur et se congèlent 3 mois. Réchauffer 10 minutes au four à 200 °C. La sauce au yaourt se garde 2 jours, à part.'),
  ('farfalle-saumon-epinards', 'Des pâtes à la crème, aux épinards et au zeste de citron, avec du saumon fumé ajouté au dernier moment. Un plat rapide et raffiné, prêt en 20 minutes.', 'À déguster de préférence tout de suite. Se garde 1 jour au réfrigérateur. Réchauffer à feu doux avec un filet d''eau. Ne se congèle pas.'),
  ('filet-mignon-miel-moutarde', 'Un rôti tendre laqué au miel et à la moutarde, cuit au four avec des carottes qui caramélisent dans le jus. Un plat de fête simple, qui se cuisine presque tout seul.', 'Se garde 3 jours au réfrigérateur. Se déguste aussi froid, en fines tranches. Réchauffer à couvert au four à 150 °C, avec un peu de jus. Se congèle 2 mois, tranché.'),
  ('frittata-legumes', 'L''omelette italienne épaisse, cuite à la poêle puis terminée au four. C''est la recette idéale pour utiliser des restes de pommes de terre et de légumes. Elle se déguste chaude, tiède ou froide, en parts.', 'Se garde 2 jours au réfrigérateur. Se mange froide, ou réchauffée 10 minutes au four à 160 °C. Pratique à emporter. Ne se congèle pas bien.'),
  ('fusilli-pesto-poulet', 'Des fusilli enrobés de pesto au basilic, avec du poulet doré et des tomates cerises juste coupées. Frais et coloré, ce plat se mange chaud comme froid, et s''emporte facilement au bureau.', 'Se garde 2 jours au réfrigérateur. Se mange froid en salade ou réchauffé à la poêle avec un filet d''eau. Ne se congèle pas bien.'),
  ('galettes-pommes-de-terre', 'Des galettes de pommes de terre râpées, dorées et croustillantes, servies avec un fromage blanc à la ciboulette. Inspirées des röstis et des latkes, elles transforment quelques pommes de terre en un vrai repas.', 'Meilleures tout juste cuites. Se gardent 2 jours au réfrigérateur ; les réchauffer 10 minutes au four à 200 °C pour retrouver le croustillant. La sauce se garde 2 jours, à part. Se congèlent 2 mois, une fois cuites.'),
  ('gaspacho', 'La soupe froide andalouse : tomates, concombre, poivron et oignon mixés avec de l''huile d''olive et un trait de vinaigre. Rafraîchissante et sans cuisson, elle est idéale les jours de chaleur.', 'Se garde 2 jours au réfrigérateur dans une bouteille ou un bocal fermé. Bien mélanger avant de servir. Ne se congèle pas, elle perd sa texture.'),
  ('gnocchis-epinards-lardons', 'Des gnocchis dorés à la poêle dans la graisse des lardons, avec des épinards et une sauce crème au parmesan. Un plat express et gourmand, prêt en un quart d''heure.', 'Se garde 2 jours au réfrigérateur. Réchauffer à la poêle à feu moyen avec un filet d''eau. Ne se congèle pas bien.'),
  ('gnocchis-pesto', 'Des gnocchis poêlés jusqu''à être croustillants, mélangés au pesto avec des tomates cerises à peine chaudes. Une recette en 10 minutes, avec très peu de vaisselle.', 'Meilleurs tout juste poêlés. Se gardent 1 jour au réfrigérateur ; réchauffer à la poêle à feu moyen. Ne se congèlent pas une fois cuits.'),
  ('gratin-chou-fleur', 'Un gratin réconfortant : du chou-fleur tendre sous une béchamel à la muscade et une croûte d''emmental doré. Une bonne façon de faire aimer le chou-fleur, en accompagnement ou en plat principal.', 'Se garde 3 jours au réfrigérateur. Se congèle 2 mois. Réchauffer 20 minutes au four à 180 °C, couvert d''une feuille d''aluminium.'),
  ('gratin-courgettes', 'Des courgettes fondantes liées par un appareil aux œufs et à la crème, gratinées à l''emmental. Un plat d''été simple et économique, qui se sert chaud ou tiède.', 'Se garde 2 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C. Ne se congèle pas bien, la courgette rend de l''eau.'),
  ('gratin-dauphinois', 'Le gratin de pommes de terre à la crème, emblème du Dauphiné : des rondelles fines cuites dans le lait et la crème parfumés à l''ail et à la muscade, fondantes dessous et dorées dessus. Il se sert en accompagnement ou se suffit à lui-même.', 'Se garde 3 jours au réfrigérateur. Réchauffer 20 minutes au four à 160 °C, couvert. Ne se congèle pas bien, les pommes de terre deviennent granuleuses.'),
  ('gratin-pates-brocoli', 'Des pâtes et du brocoli réunis dans une crème aux œufs et à la muscade, puis gratinés à l''emmental. Un plat complet, économique et facile, pour faire manger des légumes sans négocier.', 'Se garde 3 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C, couvert. Se congèle 2 mois, en parts.'),
  ('gratin-poireaux-jambon', 'Des tronçons de poireaux fondants et du jambon, nappés de béchamel et gratinés à l''emmental. Un plat d''hiver doux et réconfortant, qui se prépare facilement à l''avance.', 'Se garde 3 jours au réfrigérateur. Se congèle 2 mois. Réchauffer 20 minutes au four à 180 °C, couvert d''une feuille d''aluminium.'),
  ('hachis-parmentier', 'Le grand classique familial : une viande hachée mijotée avec oignons et tomate, recouverte d''une purée maison et gratinée à l''emmental. Se prépare en grande quantité et se congèle très bien.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois, en parts ou dans un plat. Réchauffer 25 minutes au four à 180 °C, couvert, puis 5 minutes découvert pour regratiner.'),
  ('lasagnes-bolognaise', 'Des couches de pâtes, de sauce à la viande et de béchamel, gratinées à l''emmental. Le plat familial par excellence, encore meilleur réchauffé, et parfait pour cuisiner une fois et manger plusieurs fois.', 'Se gardent 3 jours au réfrigérateur et se congèlent 3 mois, en parts. Réchauffer 20 à 25 minutes au four à 180 °C, couvert d''une feuille d''aluminium.'),
  ('lasagnes-epinards-ricotta', 'Des lasagnes végétariennes généreuses : épinards et ricotta à la muscade, sauce tomate, mozzarella fondante et parmesan. Légères et pourtant très réconfortantes.', 'Se gardent 3 jours au réfrigérateur et se congèlent 3 mois, en parts. Réchauffer 20 minutes au four à 180 °C, couvert d''une feuille d''aluminium.'),
  ('lentilles-corail-dahl', 'Le plat de lentilles indien : des lentilles corail fondues dans le lait de coco et la tomate, parfumées au curcuma, au cumin et au gingembre. Onctueux, économique et prêt en une demi-heure.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Il épaissit en refroidissant : le réchauffer à feu doux avec un peu d''eau.'),
  ('lentilles-vertes-legumes', 'Des lentilles vertes mijotées avec carottes, oignon et céleri, au thym et au laurier. Un plat simple, nourrissant et économique, qui se mange chaud ou tiède.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux avec un peu d''eau. Les restes font une bonne base de salade.'),
  ('linguine-crevettes-ail', 'Des pâtes à l''italienne, avec des crevettes saisies dans une huile parfumée à l''ail, au piment et au citron. Un plat vif et léger, prêt en 20 minutes.', 'À déguster tout de suite. Se garde 1 jour au réfrigérateur ; réchauffer rapidement à la poêle, sans recuire les crevettes. Ne se congèle pas.'),
  ('macaronis-gratines', 'Des macaronis dans une sauce au cheddar et à la muscade, gratinés sous une croûte d''emmental et de chapelure. Fondants et croustillants à la fois, ils plaisent à toute la famille.', 'Se gardent 3 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C, avec un filet de lait s''ils ont séché. Se congèlent 2 mois.'),
  ('merguez-semoule-legumes', 'Un repas aux saveurs du Maghreb : des merguez grillées, des légumes et des pois chiches cuits dans un bouillon au cumin, et une semoule légère. La harissa à part relève le tout selon les goûts.', 'Les légumes et leur bouillon se gardent 3 jours au réfrigérateur ; les merguez cuites 2 jours. Réchauffer à feu doux. Les légumes se congèlent 3 mois.'),
  ('minestrone', 'La grande soupe italienne aux légumes, aux haricots blancs et aux petites pâtes. Copieuse comme un plat, elle se sert avec du parmesan et du basilic.', 'Se garde 3 jours au réfrigérateur. Les pâtes continuent de gonfler : ajouter un peu d''eau en réchauffant. Se congèle 3 mois, de préférence sans les pâtes.'),
  ('moules-marinieres', 'Le classique des bords de mer : des moules ouvertes à la vapeur du vin blanc, avec échalotes, beurre et persil. Un plat rapide et convivial, à partager avec du pain pour saucer.', 'À consommer le jour même. Les restes, décortiqués, se gardent 1 jour au réfrigérateur dans leur jus et ne se réchauffent qu''une fois. Ne se congèle pas.'),
  ('mousse-chocolat', 'La mousse au chocolat traditionnelle, avec seulement trois ingrédients : chocolat noir, œufs et un peu de sucre. Aérienne et intense, elle se prépare la veille ou le matin pour le soir.', 'Se garde 24 heures au réfrigérateur, couverte : elle contient des œufs crus. Ne pas la laisser à température ambiante. Ne se congèle pas.'),
  ('nouilles-sautees-tofu', 'Des nouilles de riz sautées au wok avec du tofu doré, des légumes croquants et une sauce soja au gingembre, parsemées de cacahuètes. Un plat végétarien rapide et plein de textures.', 'Se garde 2 jours au réfrigérateur. Réchauffer 2 à 3 minutes à la poêle à feu vif, avec un filet d''eau. Ne se congèle pas bien.'),
  ('oeufs-cocotte', 'Des œufs cuits doucement au four sur un lit de crème et de jambon, le jaune encore coulant, servis avec des mouillettes. Un repas simple et élégant, idéal pour un dîner léger ou un brunch.', 'À déguster dès la sortie du four, le jaune durcit en attendant. Ne se conserve pas et ne se congèle pas.'),
  ('omelette-champignons', 'Une omelette baveuse aux champignons dorés au beurre, relevée de persil. Un dîner prêt en 10 minutes, qui ne demande qu''une poêle.', 'À déguster tout de suite. Les restes se gardent 1 jour au réfrigérateur et se mangent froids. Ne se congèle pas.'),
  ('one-pot-pasta-legumes', 'Tout cuit ensemble dans une seule casserole : les pâtes absorbent le bouillon et l''amidon forme une sauce crémeuse avec les légumes. Une recette astucieuse, rapide, avec un minimum de vaisselle.', 'Se garde 2 jours au réfrigérateur. Les pâtes absorbent le reste de liquide : ajouter un filet d''eau en réchauffant à feu doux. Ne se congèle pas bien.'),
  ('paella-poulet-chorizo', 'Un plat de fête espagnol : du riz cuit dans un bouillon au curcuma et au paprika, avec poulet, chorizo, crevettes, poivrons et petits pois. On le pose au milieu de la table et chacun se sert.', 'Se garde 1 jour au réfrigérateur, refroidi rapidement : il contient du riz et des crevettes. Réchauffer à la poêle avec un peu d''eau, jusqu''à ce que ce soit bien chaud. Ne se congèle pas.'),
  ('pancakes', 'Des pancakes épais et moelleux, à la mode américaine, pour un petit-déjeuner ou un goûter du week-end. La pâte se prépare en 5 minutes et repose pendant qu''on chauffe la poêle.', 'Se gardent 2 jours au réfrigérateur, bien emballés, et se congèlent 2 mois, séparés par du papier. Les réchauffer au grille-pain ou 30 secondes par face à la poêle.'),
  ('papillotes-saumon-legumes', 'Du saumon cuit en papillote sur un lit de petits légumes, avec citron et thym. La vapeur enfermée garde le poisson moelleux et parfumé, sans matière grasse ni vaisselle.', 'À déguster de préférence tout de suite. Se garde 1 jour au réfrigérateur ; se mange froid, ou réchauffé à couvert 10 minutes au four à 150 °C. Ne se congèle pas.'),
  ('patates-douces-feta-pois-chiches', 'Des patates douces et des pois chiches rôtis au cumin et au paprika, relevés de feta salée, de citron et de persil. Un plat végétarien très simple, sucré-salé, qui se mange chaud ou froid.', 'Se garde 3 jours au réfrigérateur, sans la feta ni le citron. Réchauffer 10 minutes au four à 200 °C ou manger froid en salade. Ne se congèle pas bien.'),
  ('pates-thon-tomate', 'Des pâtes à la sauce tomate, au thon, aux olives et aux câpres. Un plat de placard à l''italienne, savoureux et économique, prêt en un quart d''heure.', 'Se garde 2 jours au réfrigérateur. Réchauffer à la poêle avec un filet d''eau, ou manger froid. La sauce seule se congèle 2 mois.'),
  ('pates-tomate-basilic', 'Le plat de pâtes le plus simple, et l''un des meilleurs : une sauce tomate mijotée à l''oignon et à l''ail, du basilic frais et du parmesan. La sauce se double facilement pour les jours suivants.', 'La sauce se garde 4 jours au réfrigérateur et se congèle 3 mois. Les pâtes cuites se gardent 2 jours, à part.'),
  ('penne-arrabbiata', 'Les pâtes romaines « enragées » : une sauce tomate à l''ail et au piment, simple et relevée. Dosez le piment selon votre goût.', 'Se garde 2 jours au réfrigérateur. La sauce seule se garde 4 jours et se congèle 3 mois. Réchauffer à feu doux.'),
  ('penne-courgettes-feta', 'Des pâtes fraîches et estivales : courgettes dorées, feta, menthe et citron. Un plat léger, végétarien, prêt en 20 minutes, qui se mange aussi froid.', 'Se garde 2 jours au réfrigérateur. Se mange froid ou réchauffé à la poêle. Ne se congèle pas bien.'),
  ('poelee-saucisses-lentilles', 'Un plat de bistrot simple et rustique : des saucisses dorées puis mijotées avec les lentilles vertes, les carottes, le thym et le laurier. Nourrissant et économique.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux à couvert, avec un peu d''eau.'),
  ('pommes-de-terre-farcies', 'De grosses pommes de terre cuites au four, évidées, puis farcies de leur chair écrasée avec jambon, crème et oignon, et gratinées. Un plat complet et gourmand, servi dans sa propre peau.', 'Se gardent 2 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C. Ne se congèlent pas bien.'),
  ('pommes-de-terre-oeufs-plat', 'Des pommes de terre sautées dorées à l''oignon, surmontées d''œufs au plat au jaune coulant. Un repas simple et économique, qui se cuisine avec presque rien.', 'À déguster tout de suite pour profiter du jaune coulant. Les pommes de terre seules se gardent 2 jours au réfrigérateur et se réchauffent à la poêle.'),
  ('porc-caramel', 'Un classique de la cuisine vietnamienne : du porc mijoté dans un caramel à la sauce soja, à l''ail et au gingembre, jusqu''à ce que la sauce soit sirupeuse. Sucré, salé et très parfumé.', 'Le porc et sa sauce se gardent 3 jours au réfrigérateur et se congèlent 3 mois. Le riz cuit se garde 1 jour. Réchauffer à feu doux avec un filet d''eau.'),
  ('porc-moutarde', 'Un filet mignon doré puis braisé au vin blanc, servi tranché dans une sauce à la crème et à la moutarde. Tendre, simple et élégant.', 'Se garde 2 jours au réfrigérateur. Réchauffer les tranches à feu doux dans la sauce, sans faire bouillir. Ne se congèle pas bien, la sauce à la crème tranche.'),
  ('potee-chou-saucisses', 'Une potée campagnarde généreuse : chou, carottes, pommes de terre, lardons et saucisses cuits longuement dans un bouillon. Un plat complet d''hiver, à servir avec un peu de bouillon.', 'Se garde 3 jours au réfrigérateur. Se congèle 3 mois, sans les pommes de terre qui deviennent farineuses. Réchauffer à feu doux à couvert, dans le bouillon.'),
  ('poulet-basquaise', 'Le poulet du Pays basque : des cuisses dorées puis mijotées avec poivrons, tomates, oignons et paprika. Un plat ensoleillé et parfumé, encore meilleur réchauffé.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux à couvert. Le riz cuit se garde 1 jour.'),
  ('poulet-citron-olives', 'Un poulet mijoté à la façon d''un tajine : citron, olives, gingembre, cumin et curcuma parfument une sauce légère. Servi avec de la semoule, c''est un plat simple et dépaysant.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux à couvert. La semoule se garde 2 jours, à part.'),
  ('poulet-curry-coco', 'Un curry doux de poulet au lait de coco, avec poivron et coriandre fraîche. Un plat parfumé et réconfortant, prêt en une demi-heure.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux. Le riz cuit se garde 1 jour, à part.'),
  ('poulet-grenailles-thym', 'Des cuisses de poulet rôties sur des grenailles, avec ail en chemise, thym et citron. Tout cuit dans le même plat : la peau devient croustillante et les pommes de terre se gorgent du jus.', 'Se garde 3 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C. Le poulet désossé se congèle 3 mois.'),
  ('poulet-miel-soja', 'Du poulet doré puis laqué dans une sauce au miel, à la sauce soja, à l''ail et au gingembre, brillante et collante. Servi avec du riz et du brocoli, c''est un plat sucré-salé que les enfants adorent.', 'Le poulet se garde 3 jours au réfrigérateur et se congèle 2 mois. Le riz cuit se garde 1 jour. Réchauffer à la poêle à feu moyen avec un filet d''eau.'),
  ('poulet-roti-legumes', 'Des cuisses de poulet rôties sur un lit de pommes de terre, carottes et oignons rouges aux herbes de Provence. Tout cuit ensemble dans le même plat : peu de vaisselle, beaucoup de goût.', 'Se garde 3 jours au réfrigérateur. Réchauffer 15 minutes au four à 180 °C. Le poulet désossé se congèle 3 mois.'),
  ('poulet-yaourt-epices-basmati', 'Du poulet mariné dans le yaourt et les épices, à la manière indienne, puis cuit avec l''oignon jusqu''à former une sauce onctueuse. Le yaourt attendrit la viande et adoucit le curry.', 'Le poulet et sa sauce se gardent 3 jours au réfrigérateur et se congèlent 2 mois. Le riz cuit se garde 1 jour. Réchauffer à feu doux.'),
  ('puree-saucisses', 'Une purée maison au beurre et au lait, onctueuse et parfumée à la muscade, avec des saucisses dorées. Le repas réconfort par excellence, simple et apprécié de tous.', 'Se garde 2 jours au réfrigérateur. Réchauffer la purée à feu doux avec un filet de lait, en remuant. Les saucisses cuites se congèlent 2 mois ; la purée moins bien.'),
  ('quiche-lardons', 'La quiche lorraine : une pâte brisée, des lardons dorés et un appareil aux œufs, à la crème et au lait, gratiné à l''emmental. Elle se sert chaude, tiède ou froide.', 'Se garde 3 jours au réfrigérateur. Réchauffer 10 à 15 minutes au four à 160 °C pour que la pâte reste croustillante. Se congèle 2 mois, en parts.'),
  ('quiche-thon-tomate', 'Une quiche de placard : thon, rondelles de tomate et appareil à l''emmental sur une pâte brisée moutardée. Économique, facile, et parfaite à emporter.', 'Se garde 2 jours au réfrigérateur. Réchauffer 10 à 15 minutes au four à 160 °C, ou manger froide. Se congèle 2 mois, en parts.'),
  ('ratatouille', 'Le mijoté de légumes provençal : aubergine, courgettes, poivrons et tomates cuits séparément puis réunis avec oignons, ail et herbes de Provence. Encore meilleure le lendemain, chaude ou froide.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Se mange chaude, tiède ou froide. Réchauffer à feu doux.'),
  ('rigatoni-saucisse-tomate', 'Des rigatoni dans une sauce tomate à la chair de saucisse émiettée, à l''oignon et à l''ail. Un plat italien de tous les jours, généreux et rapide.', 'Se garde 2 jours au réfrigérateur. La sauce seule se congèle 3 mois. Réchauffer à feu doux avec un filet d''eau.'),
  ('risotto-butternut', 'Un risotto crémeux à la courge butternut, au parmesan et au beurre. La courge fond dans le riz et lui donne une belle couleur orangée et un goût doux. Un plat d''automne réconfortant.', 'À déguster tout de suite, il épaissit en refroidissant. Se garde 1 jour au réfrigérateur, refroidi rapidement. Réchauffer à feu doux avec un peu d''eau chaude. Ne se congèle pas.'),
  ('risotto-champignons', 'Un risotto onctueux aux champignons dorés, au vin blanc et au parmesan. La cuisson louche par louche demande un peu d''attention, mais le résultat est crémeux.', 'À déguster tout de suite, il épaissit en refroidissant. Se garde 1 jour au réfrigérateur, refroidi rapidement. Réchauffer à feu doux avec un peu d''eau chaude. Ne se congèle pas.'),
  ('risotto-petits-pois-jambon', 'Un risotto printanier aux petits pois et au jambon, lié au parmesan et au beurre. Doux et coloré, il plaît aux enfants comme aux adultes.', 'À déguster tout de suite. Se garde 1 jour au réfrigérateur, refroidi rapidement. Réchauffer à feu doux avec un peu d''eau chaude. Ne se congèle pas.'),
  ('riz-au-lait', 'Le dessert de grand-mère : du riz cuit très lentement dans le lait vanillé jusqu''à devenir fondant et crémeux. Il se sert tiède ou froid.', 'Se garde 3 jours au réfrigérateur, couvert. Il épaissit en refroidissant : le détendre avec un peu de lait si besoin. Ne se congèle pas bien.'),
  ('riz-cantonais', 'Le riz sauté des restaurants asiatiques : riz, omelette en lanières, jambon, petits pois et sauce soja. Il est meilleur avec du riz cuit la veille, plus sec, qui ne colle pas.', 'Se garde 1 jour au réfrigérateur, refroidi rapidement. Réchauffer à la poêle à feu vif jusqu''à ce que ce soit bien chaud. Ne se congèle pas.'),
  ('riz-haricots-rouges', 'Du riz mélangé à des haricots rouges mijotés avec poivron, tomate, cumin et paprika. Un plat complet végétarien, inspiré des cuisines créoles et d''Amérique latine.', 'Se garde 1 jour au réfrigérateur, refroidi rapidement, à cause du riz. Les haricots seuls se gardent 3 jours et se congèlent 3 mois. Réchauffer à feu doux avec un peu d''eau.'),
  ('riz-saute-legumes-oeuf', 'Un riz sauté express aux carottes, petits pois et œufs brouillés, relevé de sauce soja. Parfait pour utiliser un reste de riz.', 'Se garde 1 jour au réfrigérateur, refroidi rapidement. Réchauffer à la poêle à feu vif jusqu''à ce que ce soit bien chaud. Ne se congèle pas.'),
  ('rougail-saucisses', 'Le plat emblématique de La Réunion : des saucisses mijotées dans une sauce tomate à l''oignon, à l''ail, au gingembre et au curcuma, plus ou moins pimentée. Généreux et parfumé.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux à couvert. Le riz cuit se garde 1 jour, à part.'),
  ('salade-boulgour-legumes-rotis', 'Une salade complète : boulgour, légumes du soleil rôtis, feta, menthe et citron. Elle se prépare à l''avance et se transporte facilement pour les déjeuners de la semaine.', 'Se garde 3 jours au réfrigérateur dans une boîte hermétique. Ajouter la menthe au dernier moment pour qu''elle reste fraîche. Ne se congèle pas.'),
  ('salade-cesar-poulet', 'La salade venue d''Amérique : salade croquante, poulet doré, croûtons à l''ail et sauce crémeuse au parmesan et au citron. Une salade repas complète et gourmande.', 'À assembler au dernier moment, sinon la salade et les croûtons ramollissent. Le poulet cuit se garde 2 jours, la sauce 1 jour, au réfrigérateur et à part.'),
  ('salade-chevre-chaud', 'Le classique des brasseries : des toasts de chèvre fondant au miel sur une salade aux noix et au vinaigre balsamique. Simple, rapide et toujours apprécié.', 'À servir aussitôt, le chèvre doit être chaud et la salade croquante. Les toasts se préparent à l''avance et s''enfournent au dernier moment.'),
  ('salade-grecque', 'La salade d''été grecque : tomates, concombre, poivron, oignon rouge, olives et feta, à l''huile d''olive et aux herbes. Fraîche, sans cuisson, prête en un quart d''heure.', 'Meilleure tout de suite. Se garde 1 jour au réfrigérateur, les légumes rendent de l''eau ; l''assaisonner au dernier moment. Ne se congèle pas.'),
  ('salade-lentilles-feta', 'Une salade de lentilles vertes, tiède ou froide, avec tomates, concombre, oignon rouge, feta et vinaigrette à la moutarde. Nourrissante et idéale à préparer à l''avance.', 'Se garde 3 jours au réfrigérateur dans une boîte hermétique. Ajouter la feta et le persil au moment de servir. Ne se congèle pas.'),
  ('salade-nicoise', 'La salade de Nice : tomates, œufs durs, thon, haricots verts, olives et oignon rouge, avec une vinaigrette simple. Colorée et complète, c''est une salade repas d''été.', 'À assembler au dernier moment. Les éléments cuits se gardent 2 jours au réfrigérateur, à part ; la salade assaisonnée, 1 jour.'),
  ('salade-pates-thon', 'La salade de pâtes des pique-niques : thon, tomates cerises, maïs et œufs durs, avec une vinaigrette ou une touche de mayonnaise. Facile, économique et à emporter.', 'Se garde 1 jour au réfrigérateur si elle contient de la mayonnaise ou des œufs, 2 jours sinon. Ne pas la laisser au soleil. Ne se congèle pas.'),
  ('salade-piemontaise', 'La salade de pommes de terre des repas de famille : pommes de terre, œufs, jambon, tomates et cornichons, liés à la mayonnaise et à la moutarde. Elle se prépare à l''avance et se sert bien fraîche.', 'Se garde 1 jour au réfrigérateur, à cause de la mayonnaise et des œufs. Ne pas la laisser à température ambiante. Ne se congèle pas.'),
  ('salade-quinoa-avocat-mais', 'Une salade colorée et végétarienne : quinoa, avocat, maïs, haricots rouges et tomates cerises, relevés de citron vert et de coriandre. Fraîche, complète et rapide.', 'Se garde 2 jours au réfrigérateur sans l''avocat, à ajouter au dernier moment car il noircit. Ne se congèle pas.'),
  ('salade-riz-thon', 'La salade de riz des beaux jours : thon, maïs, tomates, poivron, œufs durs et olives, avec une vinaigrette à la moutarde. Complète, économique et facile à emporter.', 'Se garde 1 jour au réfrigérateur, refroidie rapidement, à cause du riz et des œufs. Ne pas la laisser à température ambiante. Ne se congèle pas.'),
  ('saumon-grenailles-citron', 'Des pavés de saumon rôtis au citron sur des grenailles dorées, le tout dans le même plat. Un repas simple et sain, avec très peu de préparation.', 'Se garde 1 jour au réfrigérateur. Le saumon se mange froid, émietté, ou réchauffé à couvert 10 minutes au four à 150 °C. Ne se congèle pas une fois cuit.'),
  ('saumon-riz-brocoli', 'Un saumon cuit au four, arrosé d''huile d''olive et de citron, servi avec du riz et du brocoli vapeur. Un repas équilibré et sans chichis, prêt en une demi-heure.', 'Se garde 1 jour au réfrigérateur, refroidi rapidement. Réchauffer à couvert, doucement, pour ne pas dessécher le poisson. Ne se congèle pas.'),
  ('shakshuka', 'Un plat du Maghreb et du Moyen-Orient : des œufs pochés dans une sauce tomate aux poivrons, au cumin et au paprika, servis dans la poêle avec du pain. Idéal pour un dîner simple ou un brunch.', 'À déguster tout de suite, les œufs durcissent en attendant. La sauce seule se garde 3 jours au réfrigérateur et se congèle 3 mois : il suffit de la réchauffer et d''y cuire les œufs.'),
  ('soupe-legumes-hiver', 'Une soupe de légumes d''hiver toute simple : pommes de terre, carottes, poireau et navet, mixés en velouté. Économique, douce et réconfortante.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Ajouter la crème au moment de servir si on la congèle. Réchauffer à feu doux.'),
  ('soupe-lentilles-corail-carottes', 'Une soupe veloutée de lentilles corail et de carottes au cumin, adoucie par le lait de coco. Nourrissante comme un plat, elle est prête en une demi-heure.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Elle épaissit en refroidissant : ajouter un peu d''eau en réchauffant.'),
  ('soupe-miso-legumes', 'Un bouillon asiatique léger au gingembre et à la sauce soja, garni de nouilles de riz, de tofu, de champignons, de carotte et d''épinards. Un repas chaud et réconfortant, prêt en 30 minutes.', 'Meilleur tout de suite, les nouilles gonflent. Le bouillon seul se garde 3 jours au réfrigérateur et se congèle 3 mois ; ajouter les nouilles et les épinards au moment de réchauffer.'),
  ('soupe-oignon-gratinee', 'La soupe des Halles de Paris : des oignons longuement caramélisés au beurre, un bouillon parfumé, et une croûte de pain et d''emmental gratinée. Simple et pleine de goût.', 'La soupe sans pain ni fromage se garde 3 jours au réfrigérateur et se congèle 3 mois. Gratiner au moment de servir.'),
  ('soupe-potiron', 'Un velouté d''automne doux et soyeux : potiron, pomme de terre et une touche de crème et de muscade. Simple, économique et réconfortant.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois, de préférence sans la crème. Réchauffer à feu doux.'),
  ('soupe-thai-poulet-coco', 'Une soupe inspirée de la cuisine thaïe : bouillon au lait de coco et au curry, poulet, champignons et nouilles de riz, relevé de citron vert et de coriandre. Parfumée, rassasiante et rapide.', 'Se garde 2 jours au réfrigérateur ; les nouilles gonflent, ajouter un peu d''eau. Le bouillon sans nouilles se congèle 2 mois.'),
  ('soupe-tomate-pois-chiches', 'Une soupe épicée de tomates et de pois chiches au cumin et au paprika, à moitié mixée pour garder du relief. Nourrissante, économique et prête en une demi-heure.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux.'),
  ('spaghetti-aglio-olio', 'Le plat de pâtes le plus simple d''Italie : de l''ail doré dans l''huile d''olive, du piment et du persil. Avec des ingrédients de placard, un dîner prêt en 15 minutes.', 'À déguster tout de suite. Se garde 1 jour au réfrigérateur ; réchauffer à la poêle avec un filet d''eau. Ne se congèle pas.'),
  ('spaghetti-carbonara', 'La carbonara à la romaine : des lardons croustillants et une sauce aux œufs, au parmesan et au poivre, liée par la chaleur des pâtes. Simple mais pleine de goût.', 'À déguster tout de suite, la sauce aux œufs ne supporte pas d''attendre. Les restes se gardent 1 jour au réfrigérateur ; réchauffer très doucement. Ne se congèle pas.'),
  ('steak-hache-frites-four', 'Le duo préféré des enfants, en version maison : des frites cuites au four, croustillantes avec peu d''huile, et des steaks hachés poêlés. Un repas simple et économique.', 'À déguster tout de suite. Les frites se réchauffent 5 minutes au four à 220 °C, mais perdent de leur croustillant. Les steaks cuits se gardent 1 jour au réfrigérateur.'),
  ('steak-haricots-verts', 'Un repas de bistrot : un steak saisi au beurre, des haricots verts sautés à l''ail et au persil, et des pommes de terre dorées. Simple et rapide.', 'Le steak est meilleur tout juste cuit. Les légumes se gardent 2 jours au réfrigérateur et se réchauffent à la poêle.'),
  ('taboule', 'Un taboulé frais et parfumé : de la semoule gonflée au citron et à l''huile d''olive, des tomates, du concombre et beaucoup de persil et de menthe. Sans cuisson, idéal en été.', 'Se garde 2 jours au réfrigérateur dans une boîte hermétique. Il est encore meilleur après quelques heures au frais. Ne se congèle pas.'),
  ('tacos-poulet', 'Des wraps garnis de poulet épicé au paprika et au cumin, de poivron, de crudités et d''une sauce au fromage blanc citronnée. Frais et rapide, chacun compose le sien.', 'Le poulet cuit se garde 2 jours au réfrigérateur et la sauce 2 jours, à part. Garnir les tortillas au dernier moment. Ne se congèle pas bien.'),
  ('tagliatelles-champignons-creme', 'Des tagliatelles nappées d''une sauce crémeuse aux champignons dorés, à l''échalote et à l''ail. Un plat simple et gourmand, prêt en 25 minutes.', 'Se garde 2 jours au réfrigérateur. Réchauffer à feu doux avec un filet d''eau ou de lait. Ne se congèle pas bien.'),
  ('tarte-fine-tomate-mozzarella', 'Une tarte fine et croustillante : pâte feuilletée, pesto, tomates et mozzarella, avec du basilic frais. Facile, colorée et parfaite pour l''été.', 'Meilleure tout juste sortie du four. Se garde 1 jour au réfrigérateur ; la réchauffer 8 minutes au four à 200 °C pour que la pâte redevienne croustillante.'),
  ('tarte-poireaux-chevre', 'Une tarte salée aux poireaux fondus et au fromage de chèvre, dans un appareil aux œufs et à la crème. Douce et parfumée, elle se sert chaude ou tiède.', 'Se garde 3 jours au réfrigérateur. Réchauffer 10 à 15 minutes au four à 160 °C. Se congèle 2 mois, en parts.'),
  ('tofu-croustillant-brocoli', 'Du tofu enrobé de fécule et poêlé jusqu''à être croustillant, avec du brocoli, de l''ail, du gingembre et une sauce soja au sésame. Un plat végétarien rapide et plein de textures.', 'Meilleur tout de suite, le tofu ramollit. Se garde 1 jour au réfrigérateur, comme le riz cuit. Réchauffer à la poêle à feu vif. Ne se congèle pas.'),
  ('tortilla-espagnole', 'L''omelette espagnole aux pommes de terre et à l''oignon, cuite doucement à l''huile d''olive jusqu''à être épaisse et moelleuse. Elle se sert tiède ou froide, en parts.', 'Se garde 2 jours au réfrigérateur. Elle se mange froide, en parts, ou tiédie quelques minutes au four. Ne se congèle pas.'),
  ('veloute-brocoli', 'Un velouté vert et doux de brocoli et de pomme de terre, enrichi d''un peu de crème et d''emmental. Une bonne façon de manger des légumes en hiver.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois, sans la crème ni le fromage. Réchauffer à feu doux.'),
  ('veloute-carottes-cumin', 'Un velouté de carottes doux, relevé d''une pointe de cumin et servi avec une cuillère de crème. Économique, simple et coloré.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux.'),
  ('veloute-champignons', 'Un velouté de champignons onctueux, à la crème et au persil. Raffiné et pourtant très simple, il se prépare en une demi-heure.', 'Se garde 3 jours au réfrigérateur. Se congèle 2 mois, de préférence sans la crème. Réchauffer à feu doux.'),
  ('veloute-poireaux-pommes-de-terre', 'Le velouté le plus classique : poireaux et pommes de terre fondus au beurre, mixés et adoucis par un peu de crème. Simple, économique et réconfortant.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux. Servi froid, c''est une vichyssoise.'),
  ('wraps-thon-crudites', 'Des wraps frais au thon, au maïs et à la mayonnaise, avec de la salade et de la tomate. Sans cuisson, prêts en 10 minutes, parfaits pour un pique-nique.', 'À manger dans la journée, au frais, à cause de la mayonnaise. Le mélange au thon seul se garde 1 jour au réfrigérateur. Ne se congèle pas.'),
  ('yaourt-granola-fruits', 'Un bol de petit-déjeuner simple : yaourt nature, flocons d''avoine, banane et fraises, avec un filet de miel et des amandes. Prêt en 5 minutes.', 'À préparer au moment de le manger, la banane noircit et les flocons ramollissent.')
) as v(slug, description, storage_note)
where r.slug = v.slug;
